exercise.solution:
from itertools import permutations


def next_code(digits):
    """Return the smallest rearrangement strictly greater

    than int(digits), using every sticker exactly once;
    -1 when no such rearrangement exists.
    """
    shown = int(digits)
    best = None
    for arrangement in permutations(digits):
        value = int("".join(arrangement))
        if value > shown and (best is None or value < best):
            best = value
    return best if best is not None else -1
